Pripremimo dve nasumične tačke za predikciju

Predikcija vremenske serije na novim tačkama. Pretpostavimo da želimo da predvidimo \(NO_2\) koncentraciju na dve nove lokacije (koje nisu u skupu stanica) tokom cele godine 2017.
Prvo izaberemo dve prostorne tačke (nasumično ili određeno) u okviru posmatrane oblasti i pripremimo stars objekat koji ima sve vremenske instance za te tačke (dimenzije: time × 2 new points)


set.seed(1331)
pt &lt;- st_sample(st_bbox(no2.st), 2)
t &lt;- st_get_dimension_values(no2.st, 1)
st_as_stars(list(pts = matrix(1, length(t), length(pt)))) |&gt;
    st_set_dimensions(names = c("time", "station")) |&gt;
    st_set_dimensions("time", t) |&gt;
    st_set_dimensions("station", pt) -&gt; new_pt

Priprema prostorno vremenskog grida za predikciju

# Kreiranje prostornog grida (10km raster)
grd &lt;- st_as_stars(st_bbox(no2.sf), dx = 10000, dy = 10000)

d &lt;- dim(grd)
# t4 &lt;- t[(1:4 - 0.5) * (3*24*30)]
# Pravljenje prazan stars sa dimenzijama x, y, time (4 vremenska isečka)
t4  &lt;- as.POSIXct(c("2017-01-01 12:00:00", "2017-04-01 12:00:00", "2017-07-01 12:00:00", "2017-10-01 12:00:00"), tz = "CET")

st_as_stars(pts = array(1, c(d[1], d[2], time = length(t4)))) |&gt;
    st_set_dimensions("time", t4) |&gt;
    st_set_dimensions("x", st_get_dimension_values(grd, "x")) |&gt;
    st_set_dimensions("y", st_get_dimension_values(grd, "y")) |&gt;
    st_set_crs(32632) -&gt; grd.st

Sređivanje podataka za NDVI

# Ako su obe vrednosti za jedan datum NA ostaje NA, ako nisu onda uzmi onu koja nije NA
b4_final &lt;- b4_clean |&gt; 
  group_by(date) |&gt; 
  summarise(B04 = if (all(is.na(B04))) NA_real_ else dplyr::first(na.omit(B04)),
            .groups = "drop")

b8_final &lt;- b8_clean |&gt; 
  group_by(date) |&gt; 
  summarise(B08 = if (all(is.na(B08))) NA_real_ else dplyr::first(na.omit(B08)),
            .groups = "drop")

Vremenske serije svih parcela za soju

# Ekstrakcija NDVI serije za sve parcele soje
soja_parcele &lt;- usevi_utm |&gt;  filter(crop == "soya") |&gt;  select(ceres_id, geom)

ndvi_all &lt;- map_dfr(1:nrow(soja_parcele), function(i) {
  pt &lt;- st_centroid(soja_parcele[i,])

  b4_ts &lt;- map_dfr(b4, function(r) {
    val &lt;- terra::extract(r, vect(pt), ID = FALSE)[1,1]
    tibble(ID= soja_parcele$ceres_id[i], date = get_date(r), B04 = as.numeric(val))
  })

  b8_ts &lt;- map_dfr(b8, function(r) {
    val &lt;- terra::extract(r, vect(pt), ID = FALSE)[1,1]
    tibble(ID= soja_parcele$ceres_id[i], date = get_date(r), B08 = as.numeric(val))
  })

  b4_ts &lt;- b4_ts |&gt; 
    mutate(B04 = na_if(B04, 0)) |&gt; # 0 -&gt; NA
    group_by(ID, date) |&gt;
    summarise(B04 = if (all(is.na(B04))) NA_real_ else dplyr::first(na.omit(B04)),
              .groups = "drop") |&gt;  arrange(ID, date)

  b8_ts &lt;- b8_ts |&gt; 
    mutate(B08 = na_if(B08, 0)) |&gt; # 0 -&gt; NA
  group_by(ID, date) |&gt; 
  summarise(B08 = if (all(is.na(B08))) NA_real_ else dplyr::first(na.omit(B08)),
            .groups = "drop") |&gt;  arrange(ID, date)  

  ndvi_ts &lt;- inner_join(b4_ts, b8_ts, by = c("ID", "date")) |&gt; 
    mutate(NDVI = (B08 - B04) / (B08 + B04)) |&gt; 
    arrange(date)
})

🔀 Kontrola toka
Kontrola toka u R-u omogućava uslovno izvršavanje koda pomoću if, else if i else blokova.


Kontrola toka if-else


if (logicki uslov) {
  # Deo koda za slucaj TRUE
} else {
  # Deo koda za skucaj FALSE
}


Primer

# y vece od 10?
y = sample(1:20, size = 1)
if (y &gt; 10) {
  print("Vece od 10")
} else {
  print("Manje od 10")
}

[1] "Vece od 10"

